import sys
MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    y = [n + 1] + [0] * n + [0]
    for k in range(n):
        x, v = data[1 + 2*k:3 + 2*k]
        y[x] = v
    dp = [0] * (n + 2)
    dp[0] = 1
    for b in range(1, n + 2):
        low = y[b]
        total = 0
        for a in range(b):
            if y[a] <= low or dp[a] == 0:
                continue
            high = y[a]
            vals = [y[k] for k in range(a+1, b) if low < y[k] < high]
            mins = []
            cur = n + 1
            for v in vals:
                if v < cur:
                    cur = v
                mins.append(cur)
            mx = 0
            valid = True
            for k in range(len(vals)-1, -1, -1):
                v = vals[k]
                if v == mins[k] and v > mx:
                    valid = False
                    break
                if v > mx:
                    mx = v
            if valid:
                total += dp[a]
        dp[b] = total % MOD
    print(dp[n+1])

if __name__ == '__main__':
    main()

