import sys

MOD = 998244353

def main():
    it = iter(map(int, sys.stdin.buffer.read().split()))
    n = next(it)
    m = next(it)
    # lim[l][x]: smallest right endpoint of a forbidden interval
    # centered at x whose left endpoint is at least l.
    lim = [[n + 1] * n for _ in range(n + 1)]
    for _ in range(m):
        l = next(it) - 1
        r = next(it)
        x = next(it) - 1
        if r < lim[l][x]:
            lim[l][x] = r
    for l in range(n - 1, -1, -1):
        a = lim[l]
        b = lim[l + 1]
        for x in range(l, n):
            if b[x] < a[x]:
                a[x] = b[x]

    inv = [0] * (n + 1)
    inv[1] = 1
    for i in range(2, n + 1):
        inv[i] = MOD - (MOD // i) * inv[MOD % i] % MOD

    # dp[l][r] counts valid relative orders on [l,r), divided by (r-l)!.
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        dp[i][i] = 1
    for l in range(n - 1, -1, -1):
        row = dp[l]
        bound = lim[l]
        for r in range(l + 1, n + 1):
            total = 0
            for x in range(l, r):
                if r < bound[x]:
                    total += row[x] * dp[x + 1][r]
            row[r] = total % MOD * inv[r - l] % MOD

    answer = dp[0][n]
    for i in range(2, n + 1):
        answer = answer * i % MOD
    print(answer)

if __name__ == '__main__':
    main()

