import sys
from collections import deque

MOD = 998244353


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[0], data[1]
    a = [v - 1 for v in data[2:]]

    indeg = [0] * n
    for v in a:
        indeg[v] += 1

    queue = deque(i for i in range(n) if indeg[i] == 0)
    # None represents a row consisting entirely of ones.
    dp = [None] * n

    while queue:
        u = queue.popleft()
        v = a[u]
        child = dp[u]
        parent = dp[v]

        if parent is None:
            if child is None:
                parent = list(range(1, m + 1))
            else:
                parent = [0] * m
                total = 0
                for j in range(m):
                    total = (total + child[j]) % MOD
                    parent[j] = total
            dp[v] = parent
        elif child is None:
            for j in range(m):
                parent[j] = parent[j] * (j + 1) % MOD
        else:
            total = 0
            for j in range(m):
                total = (total + child[j]) % MOD
                parent[j] = parent[j] * total % MOD

        dp[u] = None
        indeg[v] -= 1
        if indeg[v] == 0:
            queue.append(v)

    answer = 1
    for i in range(n):
        if indeg[i] == 0:
            continue

        # All vertices of a directed cycle must have equal values.
        cur = i
        combined = None
        while indeg[cur]:
            indeg[cur] = 0
            row = dp[cur]
            if row is not None:
                if combined is None:
                    combined = row
                else:
                    for j in range(m):
                        combined[j] = combined[j] * row[j] % MOD
            dp[cur] = None
            cur = a[cur]

        ways = m if combined is None else sum(combined) % MOD
        answer = answer * ways % MOD

    print(answer)


if __name__ == '__main__':
    main()

