import sys
import math

MOD = 998244353


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    factors = {}
    for i, x in enumerate(data[1:]):
        p = 2
        while p * p <= x:
            if x % p == 0:
                e = 0
                while x % p == 0:
                    x //= p
                    e += 1
                if p not in factors:
                    factors[p] = [0] * (n - 1)
                factors[p][i] = e
            p += 1
        if x > 1:
            if x not in factors:
                factors[x] = [0] * (n - 1)
            factors[x][i] = 1

    answer = 1
    for p, steps in factors.items():
        g = 0
        for e in steps:
            g = math.gcd(g, e)
        steps = [e // g for e in steps]
        base = pow(p, g, MOD)
        powers = [1]
        for _ in range(sum(steps)):
            powers.append(powers[-1] * base % MOD)

        # Heights are normalized so that the minimum seen so far is zero.
        # dp[h] sums the products for prefixes ending at height h.
        dp = [1]
        for i, e in enumerate(steps, 1):
            if e == 0:
                dp = [v * w % MOD for v, w in zip(dp, powers)]
                continue

            length = len(dp)
            up = [0] * e + dp
            down = dp[e:]
            down += [0] * (length + e - len(down))
            next_dp = [
                (u + d) * w % MOD
                for u, d, w in zip(up, down, powers)
            ]

            # A downward step below zero raises all i previous heights.
            extra = 0
            for h in range(min(e, length)):
                extra += dp[h] * pow(base, (e - h) * i, MOD)
            next_dp[0] = (next_dp[0] + extra) % MOD
            dp = next_dp

        answer = answer * (sum(dp) % MOD) % MOD

    print(answer)


if __name__ == '__main__':
    solve()

