import sys


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    values = data[1:]
    limit = max(values)

    # omega[x] is the number of prime factors of x, with multiplicity.
    omega = bytearray(limit + 1)
    for p in range(2, limit + 1):
        if omega[p] == 0:
            power = p
            while power <= limit:
                for multiple in range(power, limit + 1, power):
                    omega[multiple] += 1
                power *= p

    # A proper divisor can have any smaller prime-factor count, so the
    # Grundy number of a component x is omega[x].
    nim_sum = 0
    for value in values:
        nim_sum ^= omega[value]

    print('Anna' if nim_sum else 'Bruno')


if __name__ == '__main__':
    main()

