from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        buckets = [[] for _ in range(n + 1)]
        for i, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            buckets[b].append((a, i))

        gains = [0] * len(conflictingPairs)
        first = second = 0
        owner = 0
        total = 0

        for right in range(1, n + 1):
            # Maintain the two largest active left endpoints, including ties.
            for left, i in buckets[right]:
                if left > first:
                    second = first
                    first = left
                    owner = i
                elif left > second:
                    second = left

            # Valid starts are first + 1 through right. Removing the
            # strongest restriction lowers this bound to second.
            total += right - first
            gains[owner] += first - second

        return total + max(gains)

