import sys
from functools import lru_cache


def main():
    A, B, M = map(int, sys.stdin.buffer.read().split())
    n = A * B - 1

    # Count linear extensions of the rectangular grid with its
    # upper-right cell contracted into its left neighbor.
    if A < B:
        caps = (B,) * (A - 1) + (B - 1,)
        required = (0,) + (1,) * (A - 2) + (2,)

        @lru_cache(None)
        def dp(s):
            if s == caps:
                return 1
            total = 0
            previous = B + 1
            for i, x in enumerate(s):
                if x < caps[i] and previous >= x + required[i]:
                    total += dp(s[:i] + (x + 1,) + s[i + 1:])
                previous = x
            return total % M

        count = dp((0,) * A)
    else:
        caps = (A - 1,) + (A,) * (B - 1)

        @lru_cache(None)
        def dp(s):
            if s == caps:
                return 1
            total = 0
            previous = A + 1
            for i, x in enumerate(s):
                if x < caps[i] and (
                    previous > x or (i == 1 and x == A - 1)
                ):
                    total += dp(s[:i] + (x + 1,) + s[i + 1:])
                previous = x
            return total % M

        count = dp((0,) * B)

    # Hook-length formula for (A, ..., A, A-1).
    factorial = 1
    for k in range(1, n + 1):
        factorial = factorial * k % M
    hooks = 1
    for r in range(B):
        width = A - (r == B - 1)
        for c in range(width):
            right = width - c - 1
            below = B - r - 1 - (c == A - 1)
            hooks = hooks * (right + below + 1) % M
    tableaux = factorial * pow(hooks, M - 2, M) % M
    print(count * tableaux % M)


if __name__ == '__main__':
    main()

