import sys
from math import gcd


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, budget = data[:2]
    machines = []
    upper = 10**18

    for i in range(n):
        a, p, b, q = data[2 + 4*i:6 + 4*i]
        # S has at least as much capacity per yen as T.
        if a*q < b*p:
            a, p, b, q = b, q, a, p
        # This many T machines can be replaced by S machines
        # with equal capacity and no greater cost.
        limit = a // gcd(a, b)
        machines.append((a, p, b, q, limit))
        upper = min(upper, budget*a//p)

    def feasible(w):
        total = 0
        for a, p, b, q, limit in machines:
            best = ((w+a-1)//a)*p
            for t in range(1, min(limit-1, (w+b-1)//b)+1):
                remaining = w-t*b
                cost = t*q
                if remaining > 0:
                    cost += ((remaining+a-1)//a)*p
                if cost < best:
                    best = cost
            total += best
            if total > budget:
                return False
        return True

    low, high = 0, upper+1
    while high-low > 1:
        mid = (low+high)//2
        if feasible(mid):
            low = mid
        else:
            high = mid
    print(low)


if __name__ == '__main__':
    main()

