class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        length = len(s)

        # steps[x] is the number of operations needed to reduce x to 1.
        steps = [0] * (length + 1)
        for x in range(2, length + 1):
            steps[x] = 1 + steps[x.bit_count()]
        good = [x for x in range(1, length + 1) if steps[x] < k]

        fact = [1] * (length + 1)
        for i in range(1, length + 1):
            fact[i] = fact[i - 1] * i % MOD
        invfact = [1] * (length + 1)
        invfact[length] = pow(fact[length], MOD - 2, MOD)
        for i in range(length, 0, -1):
            invfact[i - 1] = invfact[i] * i % MOD

        answer = 0
        prefix_ones = 0
        for i, bit in enumerate(s):
            if bit == '1':
                # Match the preceding prefix and put 0 at this position.
                remaining = length - i - 1
                for total in good:
                    needed = total - prefix_ones
                    if needed < 0:
                        continue
                    if needed > remaining:
                        break
                    answer += (fact[remaining] * invfact[needed] % MOD
                               * invfact[remaining - needed] % MOD)
                answer %= MOD
                prefix_ones += 1
        return answer

