import sys


def solve(a):
    if len(a) <= 1:
        return len(a), len(a)

    even = []
    odd = []
    c0 = c1 = c2 = c3 = 0
    for v in a:
        r = v & 3
        if r == 0:
            c0 += 1
            even.append(v >> 1)
        elif r == 1:
            c1 += 1
            odd.append((v + 1) >> 1)
        elif r == 2:
            c2 += 1
            even.append(v >> 1)
        else:
            c3 += 1
            odd.append((v + 1) >> 1)

    e0, e1 = solve(even)
    o0, o1 = solve(odd)
    return max(e0 + c3, e1 + c1), max(o0 + c2, o1 + c0)


