    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[:2]
    rows = [0] * n
    for i in range(m):
        u, v = data[2 + 2 * i] - 1, data[3 + 2 * i] - 1
        rows[u] |= 1 << v
        rows[v] |= 1 << u

    # Reduced row echelon form of the adjacency matrix over GF(2).
    pivots = []
    r = 0
    for c in range(n):
        p = next((i for i in range(r, n) if (rows[i] >> c) & 1), None)
        if p is None:
            continue
        rows[r], rows[p] = rows[p], rows[r]
        for i in range(n):
            if i != r and (rows[i] >> c) & 1:
                rows[i] ^= rows[r]
        pivots.append(c)
        r += 1

    # Put each nullspace basis vector in a separate bit position.
    pivot_set = set(pivots)
    ans = [0] * n
    k = 0
    for f in range(n):
