        bit = 1 << k
        ans[f] |= bit
        for i, p in enumerate(pivots):
            if (rows[i] >> f) & 1:
                ans[p] |= bit
        k += 1

    # A zero coordinate in every basis vector is necessarily always zero.
    if any(x == 0 for x in ans):
