from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i
        remaining = list(range(1, n + 1))
        odd, even = (n + 1) // 2, n // 2
        answer = []
        last = -1
        for pos in range(n):
            for i, x in enumerate(remaining):
                parity = x % 2
                if parity == last:
                    continue
                o = odd - parity
                e = even - (1 - parity)
                length = n - pos - 1
                needed_odd = length // 2 + (length % 2 if parity == 0 else 0)
                if o != needed_odd:
                    continue
                count = fact[o] * fact[e]
                if k > count:
                    k -= count
                else:
                    answer.append(x)
                    remaining.pop(i)
                    odd, even = o, e
                    last = parity
                    break
            else:
                return []
        return answer

