class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        h = (n + 1) // 2
        powers = [1 % k] * n
        for i in range(1, n):
            powers[i] = powers[i - 1] * 10 % k

        weights = [
            powers[i] if i == n - 1 - i
            else (powers[i] + powers[n - 1 - i]) % k
            for i in range(h)
        ]

        # Bit r records whether the remaining positions can contribute r modulo k.
        possible = [0] * (h + 1)
        possible[h] = 1
        full = (1 << k) - 1
        for i in range(h - 1, -1, -1):
            mask = possible[i + 1]
            if mask == full:
                possible[i] = full
                continue
            out = 0
            for digit in range(10):
                shift = digit * weights[i] % k
                out |= ((mask << shift) | (mask >> (k - shift))) & full
            possible[i] = out

        digits = []
        remainder = 0
        for i, weight in enumerate(weights):
            for digit in range(9, -1 if i else 0, -1):
                new_remainder = (remainder + digit * weight) % k
                if possible[i + 1] & (1 << ((-new_remainder) % k)):
                    digits.append(str(digit))
                    remainder = new_remainder
                    break

        left = ''.join(digits)
        return left + (left[:-1] if n % 2 else left)[::-1]

