class Solution:
    def maximumSubarrayXor(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        n = len(nums)
        grouped = [[] for _ in range(n)]
        for k, (l, r) in enumerate(queries):
            grouped[l].append((r, k))

        answer = [0] * len(queries)
        score = [0] * n
        best = [0] * n

        # Before each row, entries at r store results for [l + 1, r].
