class Solution:
    def makeStringGood(self, s: str) -> int:
        counts = [0] * 26
        for c in s:
            counts[ord(c) - 97] += 1
        answer = len(s)
        for target in range(1, max(counts) + 1):
            dp = [0] * 28
            for i in range(25, -1, -1):
                x = counts[i]
                best = min(x, abs(x - target)) + dp[i + 1]
                if i < 25 and counts[i + 1] < target:
                    surplus = x - target if x >= target else x
                    paired = max(surplus, target - counts[i + 1]) + dp[i + 2]
                    best = min(best, paired)
                dp[i] = best
            answer = min(answer, dp[0])
        return answer

