import sys


def solve(n, a, b):
    if a == b:
        return 0
    if a.count(b'1') < b.count(b'1'):
        return -1

    lead = b.find(b'1')
    tail = n - 1 - b.rfind(b'1')
    first = a.find(b'1')
    last = a.rfind(b'1')
    low = max(abs(first - lead), abs(last - (n - 1 - tail)))

    runs = []
    i = lead
    stop = n - tail
    while i < stop:
        j = i + 1
        while j < stop and b[j] == b[i]:
            j += 1
        runs.append(j - i if b[i] == 49 else b'0' * (j - i))
        i = j

    def possible(t):
        p = lead - t
        end = n + t - tail
        for run in runs:
            if isinstance(run, int):
                remaining = run
                while remaining:
                    x = a.find(b'1', max(p, 0))
                    if x < 0:
                        return False
                    p = x + 1 + ((x - p) & 1)
                    remaining -= 1
                    if p > end:
                        return False
                    # Consume a consecutive stretch of ones in one batch.
                    if remaining and p < n and a[p] == 49:
                        z = a.find(b'0', p)
                        if z < 0:
                            z = n
                        take = min(remaining, z - p)
                        p += take
                        remaining -= take
            else:
                x = a.find(run, p)
                while x >= 0 and ((x - p) & 1):
                    x = a.find(run, x + 1)
