import sys


def main():
    k = int(sys.stdin.buffer.readline())
    s = sys.stdin.buffer.readline().strip()
    t = sys.stdin.buffer.readline().strip()
    n, m = len(s), len(t)

    if abs(n - m) > k:
        print('No')
        return

    x = 0
    while x < n and x < m and s[x] == t[x]:
        x += 1
    if x == n and x == m:
        print('Yes')
        return

    # For each diagonal d = x-y, store the farthest reachable x.
    prev = {0: x}
    for edits in range(1, k + 1):
        cur = {}
        for d in range(max(-edits, -m), min(edits, n) + 1):
            x = prev.get(d, -1)
            # Replace, or retain a state using fewer operations.
            if x >= 0 and x < n and x - d < m:
                x += 1

            # Delete one character of s.
            p = prev.get(d - 1, -1)
            if p >= 0 and p < n and p + 1 > x:
                x = p + 1

            # Insert one character from t.
            p = prev.get(d + 1, -1)
            if p >= 0 and p - d - 1 < m and p > x:
                x = p

            if x < 0:
                continue
            y = x - d
            while x < n and y < m and s[x] == t[y]:
                x += 1
                y += 1
            cur[d] = x
            if x == n and y == m:
                print('Yes')
                return
        prev = cur

    print('No')


if __name__ == '__main__':
    main()

