from typing import List

class Solution:
    def maxEnergyBoost(self, energyDrinkA: List[int], energyDrinkB: List[int]) -> int:
        # a and b end at the preceding hour; old_a and old_b
        # end two hours back, allowing an hour off when switching.
        a = b = old_a = old_b = 0
        for x, y in zip(energyDrinkA, energyDrinkB):
            next_a = x + max(a, old_b)
            next_b = y + max(b, old_a)
            old_a, old_b = a, b
            a, b = next_a, next_b
        return max(a, b)

