def main():
    n = int(sys.stdin.buffer.read())
    m = isqrt(n)
    limit = max(2, m // 2)

    sieve = bytearray(b'\x01') * (limit + 1)
    sieve[0:2] = b'\x00\x00'
    for p in range(2, isqrt(limit) + 1):
        if sieve[p]:
            start = p * p
            sieve[start::p] = b'\x00' * ((limit - start) // p + 1)
    primes = [p for p in range(2, limit + 1) if sieve[p]]

    answer = 0
    for p in primes:
        if p ** 8 > n:
            break
        answer += 1

    j = len(primes) - 1
    for i, p in enumerate(primes):
        if p * p >= m:
            break
        while j > i and p * primes[j] > m:
            j -= 1
        if j <= i:
            break
        answer += j - i

    print(answer)


