def main():
    data = sys.stdin.buffer
    n, q = map(int, data.readline().split())
    s = bytearray(data.readline().strip())
    count = s.count(b'ABC')
    out = []
    for _ in range(q):
        x, c = data.readline().split()
        x = int(x) - 1
        if s[x] != c[0]:
            lo = max(0, x - 2)
            hi = min(n - 3, x) + 1
            for j in range(lo, hi):
                if s[j] == 65 and s[j+1] == 66 and s[j+2] == 67:
                    count -= 1
            s[x] = c[0]
            for j in range(lo, hi):
                if s[j] == 65 and s[j+1] == 66 and s[j+2] == 67:
                    count += 1
        out.append(str(count))
    sys.stdout.write('\n'.join(out))

