from collections import Counter

class Solution:
    def getLargestOutlier(self, nums: List[int]) -> int:
        counts = Counter(nums)
        total = sum(nums)
        answer = -1001
        for outlier in counts:
            remainder = total - outlier
            if remainder % 2:
                continue
            special_sum = remainder // 2
            # Equal values must occupy two distinct indices.
            if counts.get(special_sum, 0) > (special_sum == outlier):
                answer = max(answer, outlier)
        return answer

