from typing import List

class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        # Bit s records whether a subset of the processed values sums to s.
        # A zero bitset marks an index that has already reached its target.
        reachable = [1 if x else 0 for x in nums]
        targets = [1 << x for x in nums]
        masks = [(1 << (x + 1)) - 1 for x in nums]
        remaining = sum(x > 0 for x in nums)
        if remaining == 0:
            return 0

        for k, (left, right, value) in enumerate(queries, 1):
            for i in range(left, right + 1):
                if reachable[i] == 0:
                    continue
                bits = reachable[i]
                bits = (bits | (bits << value)) & masks[i]
                if bits & targets[i]:
                    remaining -= 1
                    reachable[i] = 0
                else:
                    reachable[i] = bits
            if remaining == 0:
                return k
        return -1

