from heapq import heappush, heappop
from math import isqrt


class Solution:
    def minOperations(self, n: int, m: int) -> int:
        limit = 10 ** len(str(n))
        lower = limit // 10

        prime = bytearray(b'\x01') * limit
        prime[0:2] = b'\x00\x00'
        for p in range(2, isqrt(limit - 1) + 1):
            if prime[p]:
                start = p * p
                prime[start:limit:p] = b'\x00' * ((limit - 1 - start) // p + 1)

        if prime[n] or prime[m]:
            return -1

        powers = []
        p = 1
        while p < limit:
            powers.append(p)
            p *= 10

        dist = [float('inf')] * limit
        dist[n] = n
        heap = [(n, n)]

        while heap:
            cost, x = heappop(heap)
            if cost != dist[x]:
                continue
            if x == m:
                return cost

            for p in powers:
                digit = x // p % 10
                if digit < 9:
                    y = x + p
                    new_cost = cost + y
                    if not prime[y] and new_cost < dist[y]:
                        dist[y] = new_cost
                        heappush(heap, (new_cost, y))
                if digit > 0:
                    y = x - p
                    if y >= lower and not prime[y]:
                        new_cost = cost + y
                        if new_cost < dist[y]:
                            dist[y] = new_cost
                            heappush(heap, (new_cost, y))

        return -1

