from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        z = [0] * n
        left = right = 0
        for i in range(1, n):
            if i < right:
                z[i] = min(right - i, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] > right:
                left, right = i, i + z[i]

        lcp = [0] * (n + 1)
        answer = 0
        for i in range(n - 2, 0, -1):
            limit = (n + i) // 2
            if z[i] >= i:
                answer += n - 2 * i
                limit = min(limit, 2 * i - 1)
            value = nums[i]
            # Ascending order preserves the previous row at j + 1.
            for j in range(i + 1, limit + 1):
                if nums[j] == value:
                    length = lcp[j + 1] + 1
                    lcp[j] = length
                    if length >= j - i:
                        answer += 1
                else:
                    lcp[j] = 0
            for j in range(max(i + 1, limit + 1), n):
                if nums[j] == value:
                    lcp[j] = lcp[j + 1] + 1
                else:
                    lcp[j] = 0
        return answer

