import sys


def main():
    data = sys.stdin.buffer.read().split()
    s, t = data[1], data[2]
    n, m = len(s), len(t)

    if abs(n - m) > 1:
        print('No')
        return

    if n == m:
        errors = 0
        for a, b in zip(s, t):
            if a != b:
                errors += 1
                if errors > 1:
                    print('No')
                    return
        print('Yes')
        return

    # Make s the shorter string. Only one insertion can be needed.
    if n > m:
        s, t = t, s
        n, m = m, n

    i = 0
    while i < n and s[i] == t[i]:
        i += 1

    print('Yes' if s[i:] == t[i + 1:] else 'No')


if __name__ == '__main__':
    main()

