class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        active = s.count('1')
        previous = 0
        best = 0

        # Removing the ones between consecutive zero runs merges them.
        # Filling the merged run gains exactly the sizes of those zero runs.
        for block in s.split('1'):
            if block:
                length = len(block)
                if previous:
                    best = max(best, previous + length)
                previous = length

        return active + best

