class Solution:
    def countOfSubstrings(self, word: str, k: int) -> int:
        bits = {'a': 1, 'e': 2, 'i': 4, 'o': 8, 'u': 16}
        values = [bits.get(c, 0) for c in word]
        answer = 0
        n = len(word)

        for left in range(n):
            mask = 0
            consonants = 0
            for right in range(left, n):
                value = values[right]
                if value:
                    mask |= value
                else:
                    consonants += 1
                    if consonants > k:
                        break
                if mask == 31 and consonants == k:
                    answer += 1

        return answer

